    private static AthleteProfile BuildAthleteProfile(Visit visit)
    {
        var user = visit.User;
        var attrs = visit.VisitUserAttributes;
        var primarySport = visit.VisitUserSports
            .FirstOrDefault(s => s.Priority == VisitUserSportPriority.Primary);

        var persona = attrs.FirstOrDefault(a => a.Type == VisitUserAttributeType.Persona)?.Value;
        var activityLevel = attrs.FirstOrDefault(a => a.Type == VisitUserAttributeType.Ac

a)?.Value;
        var activityLevel = attrs.FirstOrDefault(a => a.Type == VisitUserAttributeType.ActivityLevel)?.Value;

        int age = 0;
        if (user.Birthdate.HasValue)
        {
            var today = DateTimeOffset.UtcNow;
            age = today.Year - user.Birthdate.Value.Year;
            if (user.Birthdate.Value.Date > today.AddYears(-age).Date)
                age--;
        }

        var sex = user.Gender switch
        {
            GenderType.Male => "M",
            GenderType.Female => "F",
            _ => "M",
        };

        return new AthleteProfile
        {
            Age = age,
            Sex = sex,
            Sport = primarySport?.Sport,
            Level = activityLevel,
            CompetitiveLevel = MapCompetitiveLevel(primarySport?.CompetitionLev

vel = activityLevel,
            CompetitiveLevel = MapCompetitiveLevel(primarySport?.CompetitionLevel),
            Persona = MapPersona(persona),
            Name = $"{user.FirstName} {user.LastName}".Trim(),
            Email = user.Email,
            DateOfBirth = user.Birthdate?.ToString("yyyy-MM-dd"),
        };
    }

