public static class BookingModuleChangePublisher
{
    public static async Task PublishAsync(
        Guid bookingId,
        Guid? incomingOrderId,
        string employeeEmail,
        IReceiptSnapshotService receiptSnapshotService,
        ITopicEventSender sender,
        CoreDbContext context,
        CancellationToken ct)
    {
        var visitId = await context.Bookings
            .AsNoTracking()
            .Where(x => x.Id == bookingId)
            .Select(x => x.VisitId)
            .FirstOrDefaultAsync(ct);

        if (visitId is Guid resolve

  .Select(x => x.VisitId)
            .FirstOrDefaultAsync(ct);

        if (visitId is Guid resolvedVisitId)
        {
            await receiptSnapshotService.CaptureVisitUpdatedSnapshotAsync(resolvedVisitId, employeeEmail, ct);
        }
        else if (incomingOrderId is Guid orderId)
        {
            await receiptSnapshotService.CaptureOrderCreatedSnapshotAsync(orderId, employeeEmail, ct);
        }

        await VisitSubscriptionPublisher.PublishVisitUpdatedAsync(sender, visitId, context, ct);
    }
}

